Port this Rust GPUI view to gpui-go, keep the behaviour identical, and add a test that proves the ticking works without waiting real seconds:

```rust
struct Stopwatch { elapsed: u32, running: bool, _ticker: Task<()>, _subs: Vec<Subscription> }

impl Stopwatch {
    fn new(settings: Entity<Settings>, cx: &mut Context<Self>) -> Self {
        let ticker = cx.spawn(async move |this, cx| loop {
            cx.background_executor().timer(Duration::from_secs(1)).await;
            if this.update(cx, |this, cx| { if this.running { this.elapsed += 1; cx.notify(); } }).is_err() { break; }
        });
        let subs = vec![cx.observe(&settings, |_, _, cx| cx.notify())];
        Self { elapsed: 0, running: true, _ticker: ticker, _subs: subs }
    }
}

impl Render for Stopwatch {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        div().flex().gap_2().p(px(8.)).child(format!("{}s", self.elapsed))
            .child(div().id("toggle").cursor_pointer().hover(|s| s.bg(rgb(0x333333)))
                .on_click(cx.listener(|this, _, _, cx| { this.running = !this.running; cx.notify(); }))
                .child(if self.running { "Pause" } else { "Resume" }))
    }
}
```

